#!/usr/bin/env node
/**
 * Scans staged diff text for disallowed commit trailers / tool branding.
 * Usage: node scripts/check-commit.mjs "$(git log -1 --format=%B)"
 */

const message = process.argv.slice(2).join(" ").toLowerCase();

const banned = [
  "co-authored-by: cursor",
  "generated by cursor",
  "made with cursor",
  "cursor agent",
];

const hits = banned.filter((b) => message.includes(b));
if (hits.length) {
  console.error("Commit message contains disallowed attribution:");
  for (const hit of hits) console.error(`  - ${hit}`);
  process.exit(1);
}

console.log("Commit message attribution check passed.");
